import std.test as st

fn abs(n: Int64) -> Int64 {
    if n < 0 { -n } else { n }
}

test "absolute value" {
    st.assertEqual(abs(-3), 3)
}

test "zero" {
    assert(abs(0) == 0, "abs of zero")
    st.assertTrue(true)
    st.assertFalse(false)
}

